  "guide.household.outlookText": "توهان جي خاندان لاءِ گڏيل مالي صحت - ايمرجنسي فنڊ ڪوريج، گڏيل دٻاءُ، ۽ مقصد. تازه ڪاري جڏهن ڪنهن ميمبر جي ڊيٽا تبديل ٿي.",
  "guide.pulse.label": "هي ڇا آهي؟",
  "guide.pulse.pressureTitle": "پريشر اسڪور",
  "guide.pulse.pressureText": "توهان جو مالي دٻاءُ جو اسڪور (0-100) اندازو ڪري ٿو ته توهان جي آمدني جو ڪيترو حصو مقرر ٿيل ذميوارين ڏانهن وڃي ٿو. 45 کان هيٺ صحتمند آهي. 70 کان مٿي جو مطلب آهي توهان جا فرض ڳري آهن.",
  "guide.pulse.freeCashTitle": "Free نقد",
  "guide.pulse.freeCashText": "پئسا هن مهيني توهان جي سڀني ادائگي جي ادائيگي کان پوء ڇڏي ويا. اھو اھو آھي جيڪو توھان کي اصل ۾ خرچ ڪرڻ، بچائڻ، يا سيڙپڪاري ڪرڻو آھي.",
